using namespace std;

int main() {
    int t;
    cin >> t;

    while (t--) {
        int n, q;
        cin >> n >> q;

        while (q--) {
            string type;
            cin >> type;

            if (type == "->") {
                int x, y;
                cin >> x >> y;
                x--, y--;

                long long num = 0;
                for (int i = n - 1; i >= 0; --i) {
                    int cur = 1 << i;
                    if (!(x & cur) && !(y & cur))
                        num ^= 0ll << (2 * i);
                    if ((x & cur) && (y & cur))
                        num ^= 1ll << (2 * i);
                    if ((x & cur) && !(y & cur))
                        num ^= 2ll << (2 * i);
                    if (!(x & cur) && (y & cur))
                        num ^= 3ll << (2 * i);
                }
                cout << num + 1 << '\n';
            }
            else {
                long long num;
                cin >> num;
                num--;

                int x = 0, y = 0;
                for (int i = n - 1; i >= 0; --i) {
                    long long cur = 3ll << (2 * i);
                    if ((num & cur) >> (2 * i) == 0)
                        x ^= 0 << i, y ^= 0 << i;
                    if ((num & cur) >> (2 * i) == 1)
                        x ^= 1 << i, y ^= 1 << i;
                    if ((num & cur) >> (2 * i) == 2)
                        x ^= 1 << i, y ^= 0 << i;
                    if ((num & cur) >> (2 * i) == 3)
                        x ^= 0 << i, y ^= 1 << i;
                }
                cout << x + 1 << ' ' << y + 1 << '\n';
            }
        }
    }

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

vector<int> nums(2e5 + 5, 0);

bool check(vector<int>& v, int k, int m)
{
    int cnt = 0;
    int cur_mex = 0;
    for (int i = 0; i < v.size(); i++) {
        if (v[i] <= v.size() + 1) {
            nums[v[i]] = 1;
        }
        while (nums[cur_mex]) {
            cur_mex++;
        }
        if (cur_mex >= m) {
            cnt++;
            for (int j = 0; j < min(m + 1, (int)v.size() + 2); j++) {
                nums[j] = 0;
            }
            cur_mex = 0;
        }
    }
    for (int j = 0; j < v.size() + 2; j++) {
        nums[j] = 0;
    }
    return cnt >= k;
}

void solve()
{
    int n, k;
    cin >> n >> k;

    vector<int> v(n);
    for (int i = 0; i < n; i++) {
        cin >> v[i];
    }

    int l = 0;
    int r = 1e9;
    while (r - l > 1) {
        int m = (r + l) / 2;
        if (check(v, k, m)) {
            l = m;
        } else {
            r = m;
        }
    }

    cout << l << '\n';
}

signed main()
{
    int t;
    cin >> t;
    for (int i = 0; i < t; i++) {
        solve();
    }
    return 0;
}

